// neon.js — NÉON, a minimalist brick breaker (zero dependencies).
//
// Brick collision is pure logic and lives in `step()` (bounce, kill, score),
// resolved with swept AABB detection so a fast ball never tunnels through a
// brick. `frame()` only renders.
//
// The module runs nothing on import: only `boot()` touches the DOM. Pure
// logic can therefore be imported from the tests (`node --test`) without a
// browser.

edits.oldText:
// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The missing bounce in frame() is what lets the ball plow
// straight through bricks (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

edits.newText:
// --- Collision (tested primitive + brick resolution) -----------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The face is resolved in step() by comparing how deep the
// ball penetrates on each axis.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Kills a brick and awards its points (combo included).
function killBrick(state, brick) {
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);
}

// Resolves an overlap against one brick: the ball bounces off the face with
// the least penetration (both faces on an exact tie — a corner) and is pushed
// back out of the rectangle so the bounce is not sticky. `flips` enforces the
// "one bounce per axis per pass" rule: two bricks overlapped in the same pass
// (a grid seam: BRICK_GAP 8 < ball diameter 14) must not cancel each other's
// bounce. Returns true when the brick was hit.
function resolveBrick(state, brick, flips) {
  const { ball } = state;
  if (!collides(ball, brick)) return false;

  const left = ball.x + ball.r - brick.x;
  const right = brick.x + brick.w - (ball.x - ball.r);
  const top = ball.y + ball.r - brick.y;
  const bottom = brick.y + brick.h - (ball.y - ball.r);
  const penX = Math.min(left, right);
  const penY = Math.min(top, bottom);

  killBrick(state, brick);

  if (penY < penX) {
    // Top or bottom face: only the vertical component flips.
    if (!flips.y) {
      ball.vy = -ball.vy;
      flips.y = true;
    }
    ball.y = ball.vy < 0 ? brick.y - ball.r : brick.y + brick.h + ball.r;
  } else if (penX < penY) {
    // Left or right face: only the horizontal component flips.
    if (!flips.x) {
      ball.vx = -ball.vx;
      flips.x = true;
    }
    ball.x = ball.vx < 0 ? brick.x - ball.r : brick.x + brick.w + ball.r;
  } else {
    // Corner: equal penetration on both axes — both components flip.
    if (!flips.x) {
      ball.vx = -ball.vx;
      flips.x = true;
    }
    if (!flips.y) {
      ball.vy = -ball.vy;
      flips.y = true;
    }
    ball.x = ball.vx < 0 ? brick.x - ball.r : brick.x + brick.w + ball.r;
    ball.y = ball.vy < 0 ? brick.y - ball.r : brick.y + brick.h + ball.r;
  }
  return true;
}

// Swept (continuous) AABB test: does the ball's segment from (prevX, prevY) to
// its current position cross the brick when neither endpoint overlaps it?
// Returns the entry time `t` and the face hit, or null. This is what stops a
// fast ball from tunneling through a brick on a single frame (the max step
// 35.5 px at level 6 exceeds the 34 px needed to clear a brick).
function sweptBrick(prevX, prevY, ball, brick) {
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;
  const minX = brick.x - ball.r;
  const maxX = brick.x + brick.w + ball.r;
  const minY = brick.y - ball.r;
  const maxY = brick.y + brick.h + ball.r;

  let txIn = 0;
  let txOut = 1;
  if (dx !== 0) {
    txIn = (minX - prevX) / dx;
    txOut = (maxX - prevX) / dx;
    if (txIn > txOut) {
      const t = txIn;
      txIn = txOut;
      txOut = t;
    }
  } else if (prevX <= minX || prevX >= maxX) {
    return null;
  }
  let tyIn = 0;
  let tyOut = 1;
  if (dy !== 0) {
    tyIn = (minY - prevY) / dy;
    tyOut = (maxY - prevY) / dy;
    if (tyIn > tyOut) {
      const t = tyIn;
      tyIn = tyOut;
      tyOut = t;
    }
  } else if (prevY <= minY || prevY >= maxY) {
    return null;
  }

  const tIn = Math.max(txIn, tyIn);
  const tOut = Math.min(txOut, tyOut);
  // tIn <= 0 means the ball started inside the expanded box (overlap or exit,
  // not an entry): penetration is resolved elsewhere and an exiting ball must
  // not bounce again.
  if (tIn >= tOut || tIn >= 1 || tIn <= 0) return null;

  const face = tyIn > txIn ? 'y' : txIn > tyIn ? 'x' : 'both';
