// --- Physics (movement + wall/brick/paddle bounces) ------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the bricks and the paddle. Brick collisions (bounce, kill, score)
// are pure logic, resolved here rather than in the render loop.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  const prevX = ball.x;
  const prevY = ball.y;
  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Brick collisions: bounce + kill + score. `flips` guards the one-bounce-
  // per-axis-per-pass rule, and the sweep only runs while no brick has been
  // hit yet (a bounce interrupts the flight path).
  const flips = { x: false, y: false };
  let hitAny = false;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    if (resolveBrick(state, brick, flips)) {
      hitAny = true;
      continue;
    }
    if (!hitAny) {
      const hit = sweptBrick(prevX, prevY, ball, brick);
      if (hit) {
        bounceSwept(state, brick, hit, prevX, prevY, flips);
        hitAny = true;
      }
    }
  }

